<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'; import axios from 'axios'; import { echo } from '@laravel/echo-vue';
type User={id:number;name:string;email:string;avatar_url:string|null;is_online?:boolean}; type Reaction={emoji:string;user_id:number}; type Message={id:number;conversation_id:number;sender_id:number;message:string|null;type:'text'|'image'|'file';file_name?:string;file_size?:number;file_url?:string;created_at:string;edited_at?:string|null;deleted_at?:string|null;sender:User;reply_to?:{id:number;message:string;sender:string}|null;reactions:Reaction[]}; type Conversation={id:number;type:'private'|'group';name:string;avatar_url:string|null;members:User[];last_message:Message|null;unread_count:number};
const props=defineProps<{conversations:Conversation[];currentUser:User}>(); const conversations=ref<Conversation[]>(props.conversations); const active=ref<Conversation|null>(null); const messages=ref<Message[]>([]); const draft=ref(''); const search=ref(''); const people=ref<User[]>([]); const showSearch=ref(false); const showGroup=ref(false); const groupName=ref(''); const selected=ref<User[]>([]); const attachment=ref<File|null>(null); const reply=ref<Message|null>(null); const busy=ref(false); const chat=ref<HTMLElement|null>(null); const fileInput=ref<HTMLInputElement|null>(null);
const initials=(name:string)=>name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(); const avatar=(u:{name:string;avatar_url:string|null})=>u.avatar_url; const time=(v?:string)=>v?new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(v)):''; const otherStatus=computed(()=>active.value?.type==='private'?(active.value.members.find(u=>u.id!==props.currentUser.id)?.is_online?'Online':'Offline'):`${active.value?.members.length??0} members`);
let searchTimer:number|undefined; watch(search,()=>{window.clearTimeout(searchTimer);searchTimer=window.setTimeout(async()=>{if(!search.value.trim()){people.value=[];return} people.value=(await axios.get('/messenger/users/search',{params:{q:search.value}})).data.data},250)});
let listeningId:number|undefined; function subscribe(c:Conversation){ if(listeningId===c.id)return; if(listeningId)echo().leave('conversation.'+listeningId); listeningId=c.id; echo().private('conversation.'+c.id).listen('.message.sent',(event:{message:Message})=>{ if(event.message.sender_id!==props.currentUser.id&&!messages.value.some(m=>m.id===event.message.id)){ messages.value.push(event.message); c.last_message=event.message; if(active.value?.id===c.id) axios.post(`/messenger/conversations/${c.id}/read`,{message_id:event.message.id}); } }); } async function open(c:Conversation){subscribe(c);active.value=c;messages.value=[];const {data}=await axios.get(`/messenger/conversations/${c.id}/messages`);messages.value=data.data; c.unread_count=0; await axios.post(`/messenger/conversations/${c.id}/read`,{message_id:messages.value.at(-1)?.id}); await nextTick();chat.value?.scrollTo({top:chat.value.scrollHeight});}
async function start(user:User){const {data}=await axios.post('/messenger/conversations/private',{user_id:user.id});let c=conversations.value.find(x=>x.id===data.data.id);if(!c){c=data.data;conversations.value.unshift(c!)}showSearch.value=false;search.value='';await open(c!)}
async function send(){if(!active.value||busy.value||(!draft.value.trim()&&!attachment.value))return;busy.value=true;const form=new FormData();form.append('message',draft.value.trim());if(reply.value)form.append('reply_to_id',String(reply.value.id));if(attachment.value)form.append('attachment',attachment.value);try{const {data}=await axios.post(`/messenger/conversations/${active.value.id}/messages`,form);messages.value.push(data.data);active.value.last_message=data.data;draft.value='';attachment.value=null;reply.value=null;await nextTick();chat.value?.scrollTo({top:chat.value.scrollHeight,behavior:'smooth'});}finally{busy.value=false}}
async function edit(m:Message){const value=window.prompt('Edit message',m.message??'');if(value?.trim()){const {data}=await axios.put(`/messenger/messages/${m.id}`,{message:value});Object.assign(m,data.data)}} async function remove(m:Message){if(window.confirm('Delete this message?')){await axios.delete(`/messenger/messages/${m.id}`);m.deleted_at=new Date().toISOString();m.message=null}} async function react(m:Message,emoji:string){const {data}=await axios.post(`/messenger/messages/${m.id}/reactions`,{emoji});Object.assign(m,data.data)}
function toggle(user:User){selected.value=selected.value.some(x=>x.id===user.id)?selected.value.filter(x=>x.id!==user.id):[...selected.value,user]} async function createGroup(){if(!groupName.value.trim()||!selected.value.length)return;const {data}=await axios.post('/messenger/groups',{name:groupName.value,members:selected.value.map(x=>x.id)});conversations.value.unshift(data.data);showGroup.value=false;groupName.value='';selected.value=[];await open(data.data)}
onMounted(()=>{if(conversations.value[0])open(conversations.value[0]);}); onUnmounted(()=>{if(listeningId)echo().leave('conversation.'+listeningId);});
</script>
<template><div class="min-h-screen bg-slate-100 p-0 sm:p-4"><main class="mx-auto flex h-[100dvh] max-w-[1500px] overflow-hidden bg-white sm:h-[calc(100dvh-2rem)] sm:rounded-3xl sm:shadow-2xl sm:shadow-slate-300/50">
<aside :class="['w-full shrink-0 border-r border-slate-100 md:w-80',active?'hidden md:flex':'flex']" class="flex-col"><div class="p-5"><div class="flex items-center justify-between"><div><p class="text-xs font-bold tracking-[.2em] text-indigo-600">PULSE</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Messages</h1></div><button @click="showSearch=true" class="rounded-xl bg-indigo-600 px-3 py-2 text-sm font-semibold text-white">New chat</button></div><div class="mt-5 flex gap-2"><input v-model="search" placeholder="Search people..." class="w-full rounded-xl bg-slate-100 px-4 py-2.5 text-sm outline-none ring-indigo-500 focus:ring-2"><button @click="showGroup=true" title="New group" class="rounded-xl bg-slate-100 px-3 text-xl">+</button></div></div><div class="min-h-0 flex-1 overflow-y-auto px-2 pb-3"><button v-for="c in conversations" :key="c.id" @click="open(c)" :class="active?.id===c.id?'bg-indigo-50':''" class="flex w-full items-center gap-3 rounded-2xl p-3 text-left hover:bg-slate-50"><div class="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-full bg-indigo-100 font-bold text-indigo-600"><img v-if="c.avatar_url" :src="c.avatar_url" class="h-full w-full object-cover"><span v-else>{{ initials(c.name) }}</span></div><div class="min-w-0 flex-1"><div class="flex justify-between gap-2"><b class="truncate text-sm text-slate-800">{{ c.name }}</b><span class="text-[11px] text-slate-400">{{ time(c.last_message?.created_at) }}</span></div><p class="truncate text-xs text-slate-500">{{ c.last_message?.sender_id===currentUser.id?'You: ':'' }}{{ c.last_message?.message||'No messages yet' }}</p></div><span v-if="c.unread_count" class="rounded-full bg-indigo-600 px-2 py-0.5 text-xs font-bold text-white">{{c.unread_count}}</span></button><p v-if="!conversations.length" class="p-8 text-center text-sm text-slate-400">No conversations yet. Start a new chat.</p></div><a href="/profile" class="border-t px-5 py-4 text-sm font-semibold text-slate-600">Profile settings</a></aside>
<section :class="['min-w-0 flex-1 flex-col',!active?'hidden md:flex':'flex']"><template v-if="active"><header class="flex items-center gap-3 border-b px-4 py-3"><button @click="active=null" class="md:hidden text-xl">‹</button><div class="flex h-10 w-10 items-center justify-center overflow-hidden rounded-full bg-indigo-100 font-bold text-indigo-600"><img v-if="active.avatar_url" :src="active.avatar_url" class="h-full w-full object-cover"><span v-else>{{initials(active.name)}}</span></div><div><h2 class="font-bold text-slate-800">{{active.name}}</h2><p class="text-xs text-emerald-600">{{otherStatus}}</p></div></header><div ref="chat" class="flex-1 overflow-y-auto bg-slate-50/70 p-4 sm:p-6"><p v-if="!messages.length" class="mt-20 text-center text-sm text-slate-400">No messages yet. Send the first hello!</p><div v-for="m in messages" :key="m.id" :class="m.sender_id===currentUser.id?'items-end':'items-start'" class="mb-4 flex flex-col"><span v-if="m.sender_id!==currentUser.id&&active.type==='group'" class="mb-1 text-xs text-slate-500">{{m.sender.name}}</span><div :class="m.sender_id===currentUser.id?'bg-indigo-600 text-white':'bg-white text-slate-700 shadow-sm'" class="max-w-[85%] rounded-2xl px-4 py-2.5 text-sm"><p v-if="m.reply_to" class="mb-2 border-l-2 border-current/40 pl-2 text-xs opacity-70">Reply to {{m.reply_to.sender}}: {{m.reply_to.message}}</p><p v-if="m.deleted_at" class="italic opacity-70">This message was deleted</p><img v-else-if="m.type==='image'" :src="m.file_url" class="max-h-64 rounded-lg"><a v-else-if="m.type==='file'" :href="m.file_url" class="underline">📄 {{m.file_name}}</a><p v-else class="whitespace-pre-wrap">{{m.message}}</p><div class="mt-1 flex items-center gap-2 text-[10px] opacity-70"><span>{{time(m.created_at)}}</span><span v-if="m.edited_at">edited</span></div></div><div class="mt-1 flex gap-1"><button @click="reply=m" class="text-xs text-slate-400">Reply</button><template v-if="m.sender_id===currentUser.id"><button @click="edit(m)" class="text-xs text-slate-400">Edit</button><button @click="remove(m)" class="text-xs text-rose-400">Delete</button></template><button v-for="emoji in ['👍','❤️','😂']" :key="emoji" @click="react(m,emoji)" class="text-xs">{{emoji}}</button></div><div v-if="m.reactions.length" class="text-xs">{{[...new Set(m.reactions.map(r=>r.emoji))].join(' ')}}</div></div></div><footer class="border-t bg-white p-3"><div v-if="reply" class="mb-2 flex justify-between rounded-lg bg-indigo-50 px-3 py-2 text-xs text-indigo-700">Replying to {{reply.sender.name}}<button @click="reply=null">×</button></div><div v-if="attachment" class="mb-2 text-xs text-slate-500">Attached: {{attachment.name}} <button @click="attachment=null">×</button></div><div class="flex items-end gap-2"><input ref="fileInput" type="file" class="hidden" accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.txt" @change="attachment=($event.target as HTMLInputElement).files?.[0]||null"><button @click="fileInput?.click()" class="rounded-xl p-2 text-xl text-slate-500" title="Attach file">＋</button><textarea v-model="draft" @keydown.enter.exact.prevent="send" placeholder="Write a message..." rows="1" class="max-h-32 flex-1 resize-none rounded-2xl bg-slate-100 px-4 py-3 text-sm outline-none ring-indigo-500 focus:ring-2"></textarea><button @click="send" :disabled="busy||(!draft.trim()&&!attachment)" class="rounded-xl bg-indigo-600 px-4 py-3 text-sm font-bold text-white disabled:opacity-40">Send</button></div></footer></template><div v-else class="m-auto text-center"><div class="text-5xl">✦</div><h2 class="mt-4 text-xl font-bold">Select a conversation</h2><p class="mt-2 text-sm text-slate-400">Choose someone from your conversations or start a new chat.</p></div></section>
</main><div v-if="showSearch||showGroup" class="fixed inset-0 grid place-items-center bg-slate-950/30 p-4"><div class="w-full max-w-md rounded-3xl bg-white p-6 shadow-xl"><div class="mb-4 flex justify-between"><h2 class="text-lg font-bold">{{showGroup?'Create group':'New conversation'}}</h2><button @click="showSearch=false;showGroup=false">×</button></div><template v-if="showGroup"><input v-model="groupName" placeholder="Group name" class="mb-3 w-full rounded-xl border px-3 py-2"><input v-model="search" placeholder="Search members" class="mb-2 w-full rounded-xl border px-3 py-2"><div class="mb-3 flex flex-wrap gap-1"><span v-for="u in selected" :key="u.id" class="rounded-full bg-indigo-50 px-2 py-1 text-xs">{{u.name}}</span></div><button @click="createGroup" class="w-full rounded-xl bg-indigo-600 py-2 font-bold text-white">Create group</button></template><input v-else v-model="search" autofocus placeholder="Search by name or email" class="mb-2 w-full rounded-xl border px-3 py-2"><button v-for="u in people" :key="u.id" @click="showGroup?toggle(u):start(u)" class="flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-slate-50"><span class="grid h-9 w-9 place-items-center rounded-full bg-indigo-100 text-xs font-bold">{{initials(u.name)}}</span><span><b class="block text-sm">{{u.name}}</b><small class="text-slate-400">{{u.email}}</small></span><span v-if="showGroup&&selected.some(x=>x.id===u.id)" class="ml-auto text-indigo-600">✓</span></button><p v-if="search&&!people.length" class="py-6 text-center text-sm text-slate-400">No users found.</p></div></div></div></template>
